package com.mathan.erp.voucher;
import com.fasterxml.jackson.databind.JsonNode;import com.mathan.erp.security.UserPrincipal;import java.util.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/vouchers") public class VoucherController {private final VoucherService service;public VoucherController(VoucherService s){service=s;}@GetMapping List<Map<String,Object>> list(@AuthenticationPrincipal UserPrincipal u,@RequestHeader("X-Business-Id")String b){return service.list(u,b);}@PostMapping Map<String,Object> create(@AuthenticationPrincipal UserPrincipal u,@RequestHeader("X-Business-Id")String b,@RequestBody JsonNode v){return service.create(u,b,v);}@PutMapping("/{id}")Map<String,Object> update(@PathVariable UUID id,@AuthenticationPrincipal UserPrincipal u,@RequestHeader("X-Business-Id")String b,@RequestBody JsonNode v){return service.update(id,u,b,v);}@PostMapping("/{id}/cancel")void cancel(@PathVariable UUID id,@AuthenticationPrincipal UserPrincipal u,@RequestHeader("X-Business-Id")String b){service.cancel(id,u,b);}}
